changeSet.sql:
CREATE TABLE IF NOT EXISTS votality_invitaciones_encuestadores (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    token VARCHAR(128) UNIQUE NOT NULL,
    campana_id UUID NOT NULL REFERENCES votality_campanas(id) ON DELETE CASCADE,
    creada_por_id UUID NOT NULL REFERENCES votality_usuarios(id) ON DELETE CASCADE,
    usada BOOLEAN NOT NULL DEFAULT FALSE,
    usada_por_id UUID REFERENCES votality_usuarios(id) ON DELETE SET NULL,
    nombre_encuestador VARCHAR(200),
    creada_el TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    usada_el TIMESTAMP WITH TIME ZONE
);

CREATE INDEX IF NOT EXISTS idx_invitacion_token ON votality_invitaciones_encuestadores(token);
CREATE INDEX IF NOT EXISTS idx_invitacion_campana_fecha ON votality_invitaciones_encuestadores(campana_id, creada_el DESC);
CREATE INDEX IF NOT EXISTS idx_invitacion_usada ON votality_invitaciones_encuestadores(usada);
